insert into public.app_settings (key, value, visibility, category, description) values ('TOAST_MESSAGES', '{"test":"Everything is wired up.","offline":"You are offline. Changes will sync when you reconnect.","online":"Back online.","otpSent":"OTP sent.","loginSuccess":"Welcome!","loginFailed":"Wrong or expired OTP. Try again.","logout":"Logged out.","onboardingDone":"All set!","username_taken":"That username is taken. Try another.","saved":"Saved.","deleted":"Deleted.","error":"Something went wrong. Please try again.","required":"Please fill all required fields.","invalidJson":"Value is not valid JSON.","permissionDenied":"You do not have access to that page.","qrRead":"QR code read.","scanSaved":"Bill saved. Stock updated for {count} items.","scanFailed":"Could not save the bill.","adminPhonesEmpty":"Keep at least one admin phone.","photoUpdated":"Profile photo updated.","photoFailed":"Could not upload the photo.","photoType":"Please choose a {types} photo.","photoTooBig":"That photo is too big. Choose one under {mb} MB.","remindersChecked":"{count} new reminder(s) created.","invalidPhone":"Enter a valid {digits}-digit mobile number.","codeCopied":"Code copied.","newLoginCode":"New login code for {phone}. Open Admin → Login codes.","invalidOtpLength":"Enter the {digits}-digit code.","otpSendFailed":"Could not send the code. Please try again.","auth.otp_expired":"Wrong or expired code. Check it and try again.","auth.over_sms_send_rate_limit":"Please wait a few seconds before asking for a new code.","auth.over_request_rate_limit":"Too many tries. Please wait a minute and try again.","auth.sms_send_failed":"Could not send the code. Please try again.","noNewReminders":"No new reminders. Stock looks fine.","newOrder":"New order request! {count} waiting in Orders.","orderPlaced":"Order sent to the shop. You will see updates here.","optionAdded":"Added \"{value}\".","paymentRecorded":"Payment recorded for {shop}. Validity extended.","shopDeactivated":"{shop} deactivated."