insert into public.app_settings (key, value, visibility, category, description) values ('ORDER_WHATSAPP', '{"accepted":"Hi {customer}, your order #{order_no} at {shop} is accepted. Total {total}. Please pay {amount_due} now. Details: {link}","packed":"Hi {customer}, your order #{order_no} at {shop} is packed. Balance {balance}. Details: {link}","ready_pickup":"Hi {customer}, your order #{order_no} is ready for pickup at {shop}. Balance {balance}. Details: {link}","ready_delivery":"Hi {customer}, your order #{order_no} from {shop} is out for delivery. Balance {balance}. Details: {link}","completed":"Thank you {customer}! Order #{order_no} from {shop} is complete.","rejected":"Sorry {customer}, {shop} could not take order #{order_no}. {remark}","cancelled":"Hi {customer}, order #{order_no} at {shop} is cancelled. {remark}","default":"Hi {customer}, about your order #{order_no} at {shop}: {link}"}'::jsonb, 'authenticated', 'texts', 'Messages the shop sends from an order (WhatsApp button). Edit in Texts & messages.') on conflict (key) do nothing;
