-- Descriptions and groups belong to the app, so they are always refreshed.
update public.app_settings set category = 'general', description = 'Name shown in the header, the browser tab and when the app is installed on a phone.' where key = 'APP_NAME';
update public.app_settings set category = 'general', description = 'Name under the app icon on the phone home screen. Keep it short.' where key = 'APP_SHORT_NAME';
update public.app_settings set category = 'general', description = 'One line about the app, shown when installing it.' where key = 'APP_DESCRIPTION';
update public.app_settings set category = 'general', description = 'Customers tap "Chat on WhatsApp" in their profile to message this number. Include the country code, e.g. 919876543210. Leave empty to hide the button.' where key = 'SUPPORT_WHATSAPP_NUMBER';
update public.app_settings set category = 'general', description = 'While on, everything created is marked as test data. Turn it off before real customers start.' where key = 'IS_TEST_MODE';
update public.app_settings set category = 'general', description = 'How dates and amounts are written. en-IN shows 13/10/2026 and ₹1,00,000.' where key = 'LOCALE';
update public.app_settings set category = 'general', description = 'Currency for all prices, e.g. INR.' where key = 'CURRENCY_CODE';
update public.app_settings set category = 'general', description = 'Used for the daily reminder time. Asia/Kolkata for India.' where key = 'TIMEZONE';
update public.app_settings set category = 'business', description = 'New shops start on the pricing plan with exactly this name (see Pricing plans).' where key = 'DEFAULT_PLAN_NAME';
update public.app_settings set category = 'business', description = 'A reminder is created when a product''s quantity drops to this number, unless the product has its own limit.' where key = 'LOW_STOCK_DEFAULT_THRESHOLD';
update public.app_settings set category = 'business', description = 'Every day at this time the app checks every shop''s stock and creates low-stock reminders.' where key = 'STOCK_REMINDER_TIME';
update public.app_settings set category = 'business', description = 'Starting store settings for new shops: pickup / delivery on or off, default payment (full, advance or cod) and advance percent. Each shop can change its own in My store.' where key = 'STORE_DEFAULTS';
update public.app_settings set category = 'business', description = 'In the store, items with this many or fewer left show "Only N left".' where key = 'STORE_LOW_AVAILABLE';
update public.app_settings set category = 'business', description = 'Units shops pick for their products (kg, pcs, …). Each shop can add its own on top of these.' where key = 'UNITS';
update public.app_settings set category = 'business', description = 'Choices customers pick from when raising a support ticket.' where key = 'ISSUE_TYPES';
update public.app_settings set category = 'business', description = 'Statuses you can set on support tickets. New tickets get the first one.' where key = 'TICKET_STATUSES';
update public.app_settings set category = 'business', description = 'Applied when a bill is added: tax_percent is added to the total; round_to rounds the total (1 = nearest rupee).' where key = 'PRICE_RULES';
update public.app_settings set category = 'login', description = 'Shown before the mobile number on the login screen, e.g. +91.' where key = 'DEFAULT_COUNTRY_CODE';
update public.app_settings set category = 'login', description = 'How many digits a mobile number has (without the country code). The login screen checks this.' where key = 'PHONE_DIGITS';
update public.app_settings set category = 'login', description = 'How many digits the login code has. Must match the OTP length in Supabase Auth settings.' where key = 'OTP_LENGTH';
update public.app_settings set category = 'login', description = 'Text of the login SMS. {otp} is replaced with the code.' where key = 'OTP_SMS_TEMPLATE';
update public.app_settings set category = 'login', description = 'How login codes reach customers. "inbox" = codes appear in Admin → Login codes and you send them on WhatsApp. "http" = a real SMS provider sends them automatically (set up once you have one).' where key = 'SMS_PROVIDER';
update public.app_settings set category = 'login', description = 'How many minutes a code stays in Login codes. Keep it the same as the OTP expiry in Supabase Auth (10 minutes).' where key = 'LOGIN_CODE_MINUTES';
update public.app_settings set category = 'login', description = 'How often (seconds) the app checks for new login codes and alerts admins on any screen.' where key = 'LOGIN_CODE_POLL_SECONDS';
update public.app_settings set category = 'login', description = 'Role given to the numbers in Admin phones.' where key = 'ADMIN_ROLE_NAME';
update public.app_settings set category = 'login', description = 'Role for people who sign up from a shop link (they can order, not run a shop).' where key = 'CUSTOMER_ROLE_NAME';
update public.app_settings set category = 'login', description = 'Role given to everyone else when they first log in.' where key = 'DEFAULT_ROLE_NAME';
update public.app_settings set category = 'appearance', description = 'Light or dark when someone opens the app. "system" follows the phone setting. Each person can still switch with the moon button; their choice is remembered.' where key = 'DEFAULT_THEME';
update public.app_settings set category = 'appearance', description = 'App colours for light and dark mode.' where key = 'THEME_COLORS';
update public.app_settings set category = 'appearance', description = 'Logo in the header: a file of the app or a web link to an image.' where key = 'APP_LOGO_URL';
update public.app_settings set category = 'appearance', description = 'Company name, link and logo in the "Powered by" line.' where key = 'BRAND';
update public.app_settings set category = 'appearance', description = 'How long pop-up messages stay on screen, in milliseconds. 3500 = 3.5 seconds.' where key = 'TOAST_DURATION_MS';
update public.app_settings set category = 'advanced', description = 'Icon files used when the app is installed.' where key = 'APP_ICONS';
update public.app_settings set category = 'advanced', description = 'Storage bucket for bill photos.' where key = 'BILLS_BUCKET';
update public.app_settings set category = 'advanced', description = 'Storage bucket for profile photos.' where key = 'AVATARS_BUCKET';
update public.app_settings set category = 'advanced', description = 'Bill photos are shrunk to max_px pixels and quality (0-1) before upload.' where key = 'BILL_IMAGE';
update public.app_settings set category = 'advanced', description = 'Allowed photo types and the largest file (max_mb). Photos are then shrunk to max_px pixels at this quality (0-1) before upload.' where key = 'AVATAR_IMAGE';
update public.app_settings set category = 'advanced', description = 'Storage bucket for product photos.' where key = 'PRODUCTS_BUCKET';
update public.app_settings set category = 'advanced', description = 'Allowed product photo types and largest file (max_mb); photos are shrunk to max_px before upload.' where key = 'PRODUCT_IMAGE';
update public.app_settings set category = 'advanced', description = 'How often (seconds) open order screens refresh and the Orders badge updates.' where key = 'ORDER_POLL_SECONDS';
update public.app_settings set category = 'advanced', description = 'Length of new shop join codes.' where key = 'STORE_JOIN_CODE_LENGTH';
update public.app_settings set category = 'advanced', description = 'How often (seconds) an open app checks for a newly deployed version and offers to update.' where key = 'UPDATE_CHECK_SECONDS';
update public.app_settings set category = 'advanced', description = 'When the app is opened again after this many seconds, the role and permissions are reloaded.' where key = 'CONTEXT_REFRESH_SECONDS';
update public.app_settings set category = 'advanced', description = 'Settings that are picked from a fixed list instead of typed.' where key = 'SETTING_CHOICES';
update public.app_settings set category = 'advanced', description = 'Camera frames per second and scan box size for the bill QR scanner.' where key = 'QR_SCANNER';
update public.app_settings set category = 'advanced', description = 'Which text groups appear in Texts & messages.' where key = 'MESSAGE_SETTINGS';
update public.app_settings set category = 'advanced', description = 'Who a setting can be sent to.' where key = 'SETTING_VISIBILITIES';
update public.app_settings set category = 'advanced', description = 'Details that can be added into a text (shown as chips when editing it), with an example value for the preview.' where key = 'TEXT_VARIABLES';
update public.app_settings set category = 'advanced', description = 'Groups on this page, in order. The last one starts collapsed.' where key = 'SETTING_CATEGORIES';
update public.app_settings set category = 'texts', description = 'Every text on screen. Edit in Texts & messages.' where key = 'UI_LABELS';
update public.app_settings set category = 'texts', description = 'Pop-up message texts. Edit in Texts & messages.' where key = 'TOAST_MESSAGES';
update public.app_settings set category = 'texts', description = 'Messages the shop sends from an order (WhatsApp button). Edit in Texts & messages.' where key = 'ORDER_WHATSAPP';
update public.app_settings set category = 'texts', description = 'Automatic notes in the order timeline. Edit in Texts & messages.' where key = 'ORDER_TEXTS';
update public.app_settings set category = 'texts', description = 'Placeholders: {product} {qty} {unit} {threshold}. Edit in Texts & messages.' where key = 'REMINDER_MESSAGES';
update public.app_settings set category = 'admin_phones', description = 'Numbers that get the admin role. Edit in Admin phones.' where key = 'ADMIN_PHONES';

-- Settings still on an earlier default move to the current default.
update public.app_settings set value = '{"provider":"inbox"}'::jsonb where key = 'SMS_PROVIDER' and value = '{"provider":"log"}'::jsonb;
update public.app_settings set value = '10'::jsonb where key = 'LOGIN_CODE_MINUTES' and value = '5'::jsonb;
update public.app_settings set value = '{"light":{"primary":"#0E9E86","onPrimary":"#FFFFFF","background":"#F3FAF8","surface":"#FFFFFF","border":"#D3EAE4","text":"#0F2A26","muted":"#5C7A74","success":"#16A34A","error":"#DC2626","warning":"#D97706","info":"#2563EB"},"dark":{"primary":"#3BC9B0","onPrimary":"#04201B","background":"#0A1614","surface":"#11211E","border":"#1F3833","text":"#E4F4F0","muted":"#8DB0A9","success":"#4ADE80","error":"#F87171","warning":"#FBBF24","info":"#60A5FA"}}'::jsonb where key = 'THEME_COLORS' and value = '{"light":{"primary":"#FFC107","onPrimary":"#1F1300","background":"#FFF8E1","surface":"#FFFFFF","border":"#F3E3B5","text":"#3E2723","muted":"#8D6E63","success":"#2E7D32","error":"#C62828","warning":"#EF6C00","info":"#1565C0"},"dark":{"primary":"#FFC107","onPrimary":"#1F1300","background":"#17130C","surface":"#241E14","border":"#3A3021","text":"#FFF8E1","muted":"#BCAAA4","success":"#66BB6A","error":"#EF5350","warning":"#FFA726","info":"#42A5F5"}}'::jsonb;
update public.app_settings set value = '{"max_px":512,"quality":0.85,"max_mb":5,"types":["image/jpeg","image/png","image/webp"]}'::jsonb where key = 'AVATAR_IMAGE' and value = '{"max_px":512,"quality":0.85}'::jsonb;
update public.app_settings set value = '["UI_LABELS","TOAST_MESSAGES","REMINDER_MESSAGES","ORDER_WHATSAPP","ORDER_TEXTS"]'::jsonb where key = 'MESSAGE_SETTINGS' and value = '["UI_LABELS","TOAST_MESSAGES","REMINDER_MESSAGES"]'::jsonb;

-- Texts still on earlier default wording move to the current wording.
update public.app_settings set value = jsonb_set(value, '{myStore.downloadQr}', '"Download to print"'::jsonb) where key = 'UI_LABELS' and value ->> 'myStore.downloadQr' = 'Download QR to print';
update public.app_settings set value = jsonb_set(value, '{messages.hint}', '"Every word in the app comes from here. Tap a text to change it; use the chips to add details like the product name. Changes apply for everyone right away."'::jsonb) where key = 'UI_LABELS' and value ->> 'messages.hint' = 'Every word in the app comes from here. Change a text and press Save; it updates for everyone right away. Keep words in {curly brackets}: the app fills them in.';
update public.app_settings set value = jsonb_set(value, '{scanSaved}', '"Bill saved. Stock updated for {count} items."'::jsonb) where key = 'TOAST_MESSAGES' and value ->> 'scanSaved' = 'Bill saved.';
update public.app_settings set value = jsonb_set(value, '{photoUpdated}', '"Profile photo updated."'::jsonb) where key = 'TOAST_MESSAGES' and value ->> 'photoUpdated' = 'Photo updated.';
update public.app_settings set value = jsonb_set(value, '{newLoginCode}', '"New login code for {phone}. Open Admin → Login codes."'::jsonb) where key = 'TOAST_MESSAGES' and value ->> 'newLoginCode' = 'New login code for {phone}.';

-- Text maps: add keys that are new in code; texts admins already edited win.
